import json
import os

CONTACTS_FILE = "contacts.json"


def load_contacts():
    if os.path.exists(CONTACTS_FILE):
        with open(CONTACTS_FILE, "r") as f:
            return json.load(f)
    return {}


def save_contacts(contacts):
    with open(CONTACTS_FILE, "w") as f:
        json.dump(contacts, f, indent=2)
    print(f"Contacts saved to {CONTACTS_FILE}")


def add_contact(contacts):
    name = input("Name: ").strip()
    if not name:
        print("Name cannot be empty.")
        return
    phone = input("Phone: ").strip()
    email = input("Email: ").strip()
    contacts[name] = {"phone": phone, "email": email}
    print(f"Added contact: {name}")


def search_contacts(contacts):
    query = input("Search query: ").strip().lower()
    results = {name: info for name, info in contacts.items() if query in name.lower()}
    if not results:
        print("No contacts found.")
        return
    for name, info in results.items():
        print(f"  {name}: phone={info['phone']}, email={info['email']}")


def delete_contact(contacts):
    name = input("Name to delete: ").strip()
    if name in contacts:
        del contacts[name]
        print(f"Deleted contact: {name}")
    else:
        print(f"Contact '{name}' not found.")


def list_contacts(contacts):
    if not contacts:
        print("No contacts.")
        return
    for name, info in contacts.items():
        print(f"  {name}: phone={info['phone']}, email={info['email']}")


def main():
    contacts = load_contacts()

    actions = {
        "1": ("Add contact", add_contact),
        "2": ("Search contacts", search_contacts),
        "3": ("Delete contact", delete_contact),
        "4": ("List all contacts", list_contacts),
        "5": ("Save and quit", None),
    }

    while True:
        print("\n--- Contact Book ---")
        for key, (label, _) in actions.items():
            print(f"  {key}. {label}")

        choice = input("Choose: ").strip()

        if choice == "5":
            save_contacts(contacts)
            break
        elif choice in actions:
            actions[choice][1](contacts)
        else:
            print("Invalid choice.")


if __name__ == "__main__":
    main()
